parameters.jsCode:
const raw = $input.first().json.choices[0].message.content;

let termine;
try {
  // Markdown-Code-Blöcke entfernen, falls vorhanden
  const cleaned = raw
    .replace(/^```json\s*/im, '')
    .replace(/^```\s*/im, '')
    .replace(/```\s*$/im, '')
    .trim();
  termine = JSON.parse(cleaned);
} catch (e) {
  throw new Error(
    `LLM-Antwort konnte nicht als JSON geparst werden: ${e.message}\n` +
    `Erste 400 Zeichen der Antwort: ${raw.slice(0, 400)}`
  );
}

if (!Array.isArray(termine)) {
  throw new Error(`Erwartet: JSON-Array. Tatsächlicher Typ: ${typeof termine}`);
}

// Jeder Termin wird zu einem separaten N8N-Item
return termine.map(t => ({ json: t }));

